        if type(value) == str:
            value = int(value)
    except ValueError:
        return False
    return 0x00 <= value <= 0xFF  # Changed from 0x00 < value to 0x00 <= value


def is_secondary_address(value):
    if value is None:
        return False

    if not isinstance(value, str):
        return False

    if len(value) != 16:
        return False

    try:
        _ = int(value, 16)
    except ValueError:
        return False

    return True


def manufacturer_id(manufacturer):
    if len(manufacturer) != 3:
        return False

    if not manufacturer.isalpha():
        return False

    manufacturer = manufacturer.upper()
    id = ((ord(manufacturer[0]) - 64) * 32 * 32 +
          (ord(manufacturer[1]) - 64) * 32 +
          (ord(manufacturer[2]) - 64))

    if 0x0421 <= id <= 0x6b5a:
        return id

    return False


def manufacturer_encode(value, size):
    if value is None or value is False:
        return None

    data = []
    for i in range(size):
        data.append((value >> ((size - 1 - i) * 8)) & 0xFF)  # Correct byte order

    return data


